    @SubscribeEvent public static void keys(net.neoforged.neoforge.client.event.RegisterKeyMappingsEvent e){e.register(SniperClient.OPEN);e.register(SniperClient.RELOAD);e.register(DmtClient.LEFT);e.register(DmtClient.RIGHT);e.register(DmtClient.RELEASE);e.register(DmtClient.REFILL);e.register(DmtClient.OPEN);e.register(DmtClient.WEAPON);e.register(DmtClient.TOGGLE);for(var k:SportsClient.KEYS)e.register(k);}
