    public static ModelResourceLocation part(String name) {
        return ModelResourceLocation.standalone(ResourceLocation.fromNamespaceAndPath(MareEletrica.ID, "block/" + name));
    }
    @SubscribeEvent public static void screens(RegisterMenuScreensEvent event) {
        event.register(br.mareeletrica.Arsenal.MENU.get(),GunScreen::new);event.register(MareEletrica.SMG_MENU.get(),SmgScreen::new);event.register(MareEletrica.RIFLE_MENU.get(),RifleScreen::new);event.register(MareEletrica.DMT_MENU.get(),DmtScreen::new);
        event.register(MareEletrica.MACHINE_MENU.get(), MachineScreen::new);event.register(MareEletrica.SERVICE_MENU.get(),ServiceScreen::new);event.register(MareEletrica.EXPLORER_MENU.get(),ExplorerScreen::new);
        event.register(MareEletrica.CONSTRUCTION_MENU.get(), ConstructionScreen::new);
        event.register(MareEletrica.MORTAR_MENU.get(), MortarScreen::new);
    }
    @SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event) { event.enqueueWork(()->{WoundsClient.init();br.mareeletrica.Skate.input=()->{var pl=net.minecraft.client.Minecraft.getInstance().player;return pl==null?new float[4]:new float[]{pl.input.forwardImpulse,pl.input.leftImpulse,pl.input.jumping?1:0,net.minecraft.client.Minecraft.getInstance().options.keySprint.isDown()?1:0};};br.mareeletrica.Fun.openArcade=ArcadeScreen::open;br.mareeletrica.Fun.pongView=ArcadeScreen::state;br.mareeletrica.Jets.startSound=JetSound::start;br.mareeletrica.GunPackets.clientShot=SniperClient::shot;br.mareeletrica.GunPackets.clientProne=SniperClient::prone;br.mareeletrica.DmtPackets.client=DmtClient::receive;br.mareeletrica.FlashNet.client=br.mareeletrica.client.FlashClient::flash;br.mareeletrica.DroneNet.sessionHandler=br.mareeletrica.client.DroneClient::session;br.mareeletrica.ControlNet.open=(pos,data)->{var mc=net.minecraft.client.Minecraft.getInstance();if(br.mareeletrica.client.CameraView.viewing())return;if(mc.screen instanceof br.mareeletrica.client.ControllerScreen s&&s.pos().equals(pos))s.update(data);else mc.setScreen(new br.mareeletrica.client.ControllerScreen(pos,data));};br.mareeletrica.SportsMode.clientAnim=SportsClient::anim;br.mareeletrica.BaseControl.openScreen=d->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof PanelScreen ps&&ps.pos().equals(d.pos()))ps.update(d.data(),d.open());else if(d.open())mc.setScreen(new PanelScreen(d.pos(),d.data()));};br.mareeletrica.Casino.openScreen=d->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof CasinoScreen cs&&cs.pos().equals(d.pos()))cs.update(d.data());else if(d.open())mc.setScreen(new CasinoScreen(d.pos(),d.data()));};br.mareeletrica.ChickenBattle.openScreen=d->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof BattleScreen bs&&bs.pos().equals(d.pos()))bs.update(d.data());else if(d.open())mc.setScreen(new BattleScreen(d.pos(),d.data()));};br.mareeletrica.Garage.openScreen=d->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof GarageScreen gs&&gs.pos().equals(d.pos()))gs.update(d.data());else mc.setScreen(new GarageScreen(d.pos(),d.data()));};br.mareeletrica.BunkerDoor.openKeypad=pos->net.minecraft.client.Minecraft.getInstance().setScreen(new br.mareeletrica.client.KeypadScreen(pos));br.mareeletrica.C4.openScreen=pos->net.minecraft.client.Minecraft.getInstance().setScreen(new br.mareeletrica.client.C4Screen(pos));br.mareeletrica.LeanNet.client=br.mareeletrica.client.LeanClient::remote;br.mareeletrica.CamoNet.client=p->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.level!=null&&mc.level.getEntity(p.entity()) instanceof net.minecraft.world.entity.player.Player player){var g=br.mareeletrica.CamoEquipment.inventory(player);g.setStackInSlot(0,p.head());g.setStackInSlot(1,p.chest());g.setStackInSlot(2,p.legs());g.setStackInSlot(3,p.feet());}};br.mareeletrica.DmtPackets.clientEquipment=p->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.level!=null&&mc.level.getEntity(p.entity()) instanceof net.minecraft.world.entity.player.Player player)br.mareeletrica.DmtEquipment.set(player,p.stack());};net.minecraft.client.renderer.ItemBlockRenderTypes.setRenderLayer(MareEletrica.PRESSURIZED_WATER.get(),net.minecraft.client.renderer.RenderType.translucent());net.minecraft.client.renderer.ItemBlockRenderTypes.setRenderLayer(MareEletrica.FLOWING_PRESSURIZED_WATER.get(),net.minecraft.client.renderer.RenderType.translucent());br.mareeletrica.RemotePackets.clientState=RemoteClient::receive;br.mareeletrica.EditorPackets.clientPaint=p->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof ConstructionScreen screen)screen.receivePaint(p);};br.mareeletrica.EditorPackets.client=p->{var mc=net.minecraft.client.Minecraft.getInstance();if(mc.screen instanceof ConstructionScreen screen)screen.receive(p);};}); }
